def semver_sort(versions):
    def parse_version(v):
        # Split by '+' to remove build metadata
        v_without_build = v.split('+')[0]

        # Split by '-' to separate core version and pre-release
        if '-' in v_without_build:
            core_part, prerelease_part = v_without_build.split('-', 1)
        else:
            core_part = v_without_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        parts = core_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease_part:
            identifiers = prerelease_part.split('.')
            # Convert identifiers to comparable form
            parsed_identifiers = []
            for identifier in identifiers:
                if identifier.isdigit():
                    parsed_identifiers.append((0, int(identifier)))
                else:
                    parsed_identifiers.append((1, identifier))
        else:
            parsed_identifiers = None

        return (major, minor, patch, parsed_identifiers)

    def compare_key(v):
        major, minor, patch, parsed_identifiers = parse_version(v)

        # For sorting: version without pre-release should come after version with pre-release
        # So we use a tuple where pre-release versions have a "smaller" second element
        if parsed_identifiers is None:
            # No pre-release: comes after versions with pre-release
            return (major, minor, patch, (1,), v)
        else:
            # Has pre-release: comes before versions without pre-release
            return (major, minor, patch, (0, tuple(parsed_identifiers)), v)

    # Sort with stable sort (maintains input order for equal precedence)
    return sorted(versions, key=compare_key)

